import java.util.List;
import java.util.concurrent.ConcurrentLinkedDeque;

import org.springframework.stereotype.Service;

/**
 * The messages sent so far, shared by every visit to the contact view.
 */
@Service
public class ContactMessageStore {

    private final ConcurrentLinkedDeque<ContactMessage> messages = new ConcurrentLinkedDeque<>();

    public void add(ContactMessage message) {
        messages.addFirst(message);
    }

    /**
     * @return all messages, newest first
     */
    public List<ContactMessage> findAll() {
        return List.copyOf(messages);
    }
}
