+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveEvent.ContinueNavigationAction;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final int MAX_MESSAGE_LENGTH = 500;
+    // The address rule browsers apply to <input type="email">, so the server agrees with the field
+    private static final Pattern EMAIL_PATTERN = Pattern.compile(
+            "^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?"
+                    + "(?:\\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$");
+
+    private final ContactMessageStore store;
+
+    private final TextField nameField = new TextField("Name");
+    private final EmailField emailField = new EmailField("Email");
+    private final TextField phoneField = new TextField("Phone");
+    private final TextArea messageField = new TextArea("Message");
+    private final Button sendButton = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    private final Dialog leaveDialog = new Dialog();
+    private ContinueNavigationAction pendingNavigation;
+
+    public ContactView(ContactMessageStore store) {
+        this.store = store;
+
+        nameField.setValueChangeMode(ValueChangeMode.EAGER);
+        emailField.setValueChangeMode(ValueChangeMode.EAGER);
+        phoneField.setValueChangeMode(ValueChangeMode.EAGER);
+        messageField.setValueChangeMode(ValueChangeMode.EAGER);
+        fields().forEach(field -> field.addValueChangeListener(e -> sendButton.setEnabled(true)));
+
+        FormLayout form = new FormLayout(nameField, emailField, phoneField, messageField);
+        form.setColspan(messageField, 2);
+
+        sendButton.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        sendButton.addClickListener(e -> send());
+        sendButton.addClickShortcut(Key.ENTER);
+
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::email).setHeader("Email");
+        grid.addColumn(ContactMessage::phone).setHeader("Phone");
+        grid.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        grid.setItems(store.findAll());
+        grid.setAllRowsVisible(true);
+
+        Button keepEditing = new Button("Keep editing", e -> keepEditing());
+        Button discard = new Button("Discard", e -> discard());
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+        leaveDialog.setHeaderTitle("Leave without sending?");
+        leaveDialog.add(new Paragraph("Your message has not been sent. Discard it and leave?"));
+        leaveDialog.getFooter().add(keepEditing, discard);
+        leaveDialog.addClosedListener(e -> cancelPendingNavigation());
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, sendButton,
+                new H2("Sent messages"), grid, leaveDialog);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (fields().stream().anyMatch(field -> !field.isEmpty())) {
+            pendingNavigation = event.postpone();
+            leaveDialog.open();
+        }
+    }
+
+    private void keepEditing() {
+        cancelPendingNavigation();
+        leaveDialog.close();
+    }
+
+    private void discard() {
+        ContinueNavigationAction navigation = pendingNavigation;
+        pendingNavigation = null;
+        leaveDialog.close();
+        navigation.proceed();
+    }
+
+    // Without this the router keeps waiting on the postponed navigation, and later clicks on the link are ignored
+    private void cancelPendingNavigation() {
+        if (pendingNavigation != null) {
+            pendingNavigation.cancel();
+            pendingNavigation = null;
+        }
+    }
+
+    private void send() {
+        if (!validate()) {
+            return;
+        }
+        store.add(new ContactMessage(
+                nameField.getValue().trim(),
+                emailField.getValue().trim(),
+                phoneField.getValue().trim(),
+                messageField.getValue().trim()));
+        grid.setItems(store.findAll());
+        Notification notification = new Notification(new Span("Message sent"));
+        notification.setDuration(5000);
+        notification.open();
+        clearForm();
+        sendButton.setEnabled(false);
+    }
+
+    private boolean validate() {
+        resetValidation();
+
+        String name = nameField.getValue().trim();
+        String email = emailField.getValue().trim();
+        String phone = phoneField.getValue().trim();
+        String message = messageField.getValue().trim();
+        boolean valid = true;
+
+        if (name.isEmpty()) {
+            invalidate(nameField, "Name is required");
+            valid = false;
+        }
+        if (!email.isEmpty() && !EMAIL_PATTERN.matcher(email).matches()) {
+            invalidate(emailField, "Enter a valid e-mail address");
+            valid = false;
+        } else if (email.isEmpty() && phone.isEmpty()) {
+            invalidate(emailField, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+        if (message.isEmpty()) {
+            invalidate(messageField, "Message is required");
+            valid = false;
+        } else if (message.codePointCount(0, message.length()) > MAX_MESSAGE_LENGTH) {
+            invalidate(messageField, "Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+            valid = false;
+        }
+        return valid;
+    }
+
+    private void clearForm() {
+        fields().forEach(AbstractField::clear);
+        resetValidation();
+    }
+
+    private void resetValidation() {
+        nameField.setInvalid(false);
+        emailField.setInvalid(false);
+        phoneField.setInvalid(false);
+        messageField.setInvalid(false);
+    }
+
+    private static void invalidate(HasValidationProperties field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private List<AbstractField<?, String>> fields() {
+        return List.of(nameField, emailField, phoneField, messageField);
+    }
+}
