+package com.example.contact;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.springframework.test.annotation.DirtiesContext;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.options.AriaRole;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+@DirtiesContext(classMode = DirtiesContext.ClassMode.AFTER_CLASS)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Override
+    public String getView() {
+        return "contact";
+    }
+
+    @Test
+    void validFormIsSentListedAndCleared() {
+        fillName("Browser Ada");
+        page.getByLabel("Email", new Page.GetByLabelOptions().setExact(true)).fill("ada@example.com");
+        page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true)).fill("Hello from a real browser");
+
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send")).click();
+
+        assertThat(page.getByText("Message sent")).isVisible();
+        assertThat(page.getByText("Hello from a real browser")).isVisible();
+        assertThat(page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true))).hasValue("");
+        assertThat(page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send"))).isDisabled();
+    }
+
+    @Test
+    void emptyFormShowsValidationErrors() {
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send")).click();
+
+        assertThat(page.getByText("Name is required")).isVisible();
+        assertThat(page.getByText("Give an e-mail address or a phone number")).isVisible();
+        assertThat(page.getByText("Message is required")).isVisible();
+        assertThat(page.getByText("Message sent")).not().isVisible();
+    }
+
+    @Test
+    void enterInTheNameFieldSends() {
+        fillName("Enter Ada");
+        page.getByLabel("Phone", new Page.GetByLabelOptions().setExact(true)).fill("+358 40 000 0000");
+        page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true)).fill("Sent with Enter key");
+
+        page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true)).press("Enter");
+
+        assertThat(page.getByText("Message sent")).isVisible();
+    }
+
+    @Test
+    void leavingAFilledFormAsksFirst() {
+        fillName("Stay Ada");
+        page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true)).fill("Not sent yet");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+
+        assertThat(page.getByText("Leave without sending?")).isVisible();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+        assertThat(page.getByText("Leave without sending?")).not().isVisible();
+        assertThat(page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true))).hasValue("Stay Ada");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard")).click();
+
+        assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About"))).isVisible();
+    }
+
+    @Test
+    void escapeClosesTheQuestionAndTheNextLinkClickAsksAgain() {
+        fillName("Esc Ada");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+        assertThat(page.getByText("Leave without sending?")).isVisible();
+        page.keyboard().press("Escape");
+        assertThat(page.getByText("Leave without sending?")).not().isVisible();
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+        assertThat(page.getByText("Leave without sending?")).isVisible();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard")).click();
+
+        assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About"))).isVisible();
+    }
+
+    private void fillName(String name) {
+        page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true)).fill(name);
+    }
+}
