+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.test.annotation.DirtiesContext;
+
+import com.example.about.AboutView;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+@DirtiesContext(classMode = DirtiesContext.ClassMode.AFTER_CLASS)
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void contactViewShowsHeadingFieldsAndAnEnabledSendButton() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void aboutLinkOpensTheAboutView() {
+        navigate(ContactView.class);
+
+        test($(RouterLink.class).single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void emptyFormReportsEveryMissingFieldAndSendsNothing() {
+        navigate(ContactView.class);
+        int before = sent().size();
+
+        test(send()).click();
+
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(name().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertFalse(phone().isInvalid());
+        assertFalse($(Notification.class).exists());
+        assertEquals(before, sent().size());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void blankNameIsRejectedAndTheTypedValuesStay() {
+        navigate(ContactView.class);
+        fill("   ", "ada@example.com", "", "Hello");
+
+        test(send()).click();
+
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(name().isInvalid());
+        assertFalse(email().isInvalid());
+        assertFalse(message().isInvalid());
+        assertEquals("ada@example.com", email().getValue());
+        assertEquals("Hello", message().getValue());
+    }
+
+    @Test
+    void malformedEmailIsRejected() {
+        navigate(ContactView.class);
+        fill("Ada", "not-an-email", "", "Hello");
+
+        test(send()).click();
+
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertFalse($(Notification.class).exists());
+    }
+
+    @Test
+    void phoneNumberAloneIsEnough() {
+        navigate(ContactView.class);
+        fill("Phone Only", "", "+358 40 123 4567", "Call me");
+
+        test(send()).click();
+
+        assertTrue($(Notification.class).withTextContaining("Message sent").exists());
+        assertEquals("Phone Only", sent().get(0).name());
+        assertEquals("+358 40 123 4567", sent().get(0).phone());
+    }
+
+    @Test
+    void emailAddressAloneIsEnough() {
+        navigate(ContactView.class);
+        fill("Mail Only", "mail@example.com", "", "Write to me");
+
+        test(send()).click();
+
+        assertTrue($(Notification.class).withTextContaining("Message sent").exists());
+        assertEquals("mail@example.com", sent().get(0).email());
+    }
+
+    @Test
+    void messageMayBeExactlyFiveHundredCharacters() {
+        navigate(ContactView.class);
+        fill("Long", "", "123", "x".repeat(500));
+
+        test(send()).click();
+
+        assertFalse(message().isInvalid());
+        assertEquals(500, sent().get(0).message().length());
+    }
+
+    @Test
+    void messageLongerThanFiveHundredCharactersIsRejected() {
+        navigate(ContactView.class);
+        fill("Too Long", "", "123", "x".repeat(501));
+
+        test(send()).click();
+
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertEquals(501, message().getValue().length());
+    }
+
+    @Test
+    void validSendNotifiesListsTheMessageClearsTheFormAndDisablesSend() {
+        navigate(ContactView.class);
+        fill("Grace", "grace@example.com", "", "Hello from the test");
+
+        test(send()).click();
+
+        assertTrue($(Notification.class).withTextContaining("Message sent").exists());
+        ContactMessage first = sent().get(0);
+        assertEquals("Grace", first.name());
+        assertEquals("grace@example.com", first.email());
+        assertEquals("Hello from the test", first.message());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertFalse(send().isEnabled());
+    }
+
+    @Test
+    void editingAnyFieldReEnablesSend() {
+        navigate(ContactView.class);
+        fill("Edit", "", "123", "Once");
+        test(send()).click();
+        assertFalse(send().isEnabled());
+
+        phone().setValue("456");
+
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void enterSendsTheMessage() {
+        navigate(ContactView.class);
+        fill("Enter Key", "", "789", "Sent with Enter");
+
+        fireShortcut(Key.ENTER);
+
+        assertTrue($(Notification.class).withTextContaining("Message sent").exists());
+        assertEquals("Sent with Enter", sent().get(0).message());
+    }
+
+    @Test
+    void sentMessagesAreStillListedAfterLeavingAndComingBack() {
+        navigate(ContactView.class);
+        fill("Persistent", "", "000", "Survives navigation");
+        test(send()).click();
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        assertEquals("Persistent", sent().get(0).name());
+        assertEquals("Survives navigation", sent().get(0).message());
+    }
+
+    @Test
+    void leavingAnEmptyFormIsNotInterrupted() {
+        navigate(ContactView.class);
+
+        test($(RouterLink.class).single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertFalse($(Dialog.class).exists());
+    }
+
+    @Test
+    void leavingAFilledFormAsksFirstAndKeepEditingStaysPut() {
+        navigate(ContactView.class);
+        fill("Keeper", "", "111", "Still typing");
+
+        test($(RouterLink.class).single()).click();
+
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertTrue($(Dialog.class).single().isOpened());
+
+        test($(Button.class).withText("Keep editing").single()).click();
+
+        assertFalse($(Dialog.class).exists());
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("Keeper", name().getValue());
+        assertEquals("Still typing", message().getValue());
+    }
+
+    @Test
+    void discardingLeavesTheFormForTheAboutView() {
+        navigate(ContactView.class);
+        fill("Discarder", "", "222", "Going away");
+
+        test($(RouterLink.class).single()).click();
+        test($(Button.class).withText("Discard").single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+    }
+
+    @SuppressWarnings("unchecked")
+    private List<ContactMessage> sent() {
+        Grid<ContactMessage> grid = $(Grid.class).single();
+        return grid.getGenericDataView().getItems().toList();
+    }
+
+    private void fill(String name, String email, String phone, String message) {
+        name().setValue(name);
+        email().setValue(email);
+        phone().setValue(phone);
+        message().setValue(message);
+    }
+
+    private TextField name() {
+        return $(TextField.class).withLabel("Name").single();
+    }
+
+    private TextField phone() {
+        return $(TextField.class).withLabel("Phone").single();
+    }
+
+    private EmailField email() {
+        return $(EmailField.class).single();
+    }
+
+    private TextArea message() {
+        return $(TextArea.class).single();
+    }
+
+    private Button send() {
+        return $(Button.class).withText("Send").single();
+    }
+}
